import numpy as np
def equation(t, x, v, params):
    c0,a1,a2,a3,a4,a5,F,w,ph,k,G = params[0],params[1],params[2],params[3],params[4],params[5],params[6],params[7],params[8],params[9],params[6]
    return c0+a1*x+a2*v+a3*x**2+a4*x*v+a5*x**2*v+F*np.cos(w*t+k*x+ph)

from scipy.optimize import least_squares
b0=[np.ones_like(x),x,v,x**2,x*v,v**2,x**3,x**2*v]
def design(p):
    w,k,m=p
    arg=w*t+k*x+m*v
    return np.column_stack(b0+[np.cos(arg),np.sin(arg),x*np.cos(arg),x*np.sin(arg)])
def res(p):
    Z=design(p)
    c2,_,_,_=np.linalg.lstsq(Z,dv_dt,rcond=None)
    return dv_dt-Z@c2
best=None
rng=np.random.default_rng(1)
for _ in range(80):
    p0=[rng.uniform(0.1,1.5),rng.uniform(-1.5,1.5),rng.uniform(-1.5,1.5)]
    try:
        r=least_squares(res,p0,method='lm',max_nfev=2000)
    except Exception: continue
    e=np.mean(r.fun**2)/np.var(dv_dt)
    if best is None or e<best[0]: best=(e,r.x)
